export type V1014CityId = 'sydney' | 'melbourne' | 'brisbane' | 'perth' | 'adelaide' | 'hobart' | 'darwin' | 'canberra' | 'newcastle' | 'wollongong' | 'geelong' | 'ballarat' | 'gold_coast' | 'sunshine_coast' | 'townsville' | 'cairns' | 'fremantle' | 'mandurah' | 'kalgoorlie' | 'mount_gambier' | 'launceston' | 'alice_springs';
export type V1014GrowthBand = 'contracting' | 'slow' | 'steady' | 'fast' | 'surging';
export type V1014CongestionBand = 'free' | 'moderate' | 'busy' | 'constrained' | 'gridlocked';
export type V1014LinkKind = 'passenger_rail' | 'freight_rail' | 'highway' | 'domestic_air' | 'sea_freight';
export type V1014LinkHealth = 'severed' | 'degraded' | 'operational' | 'strong' | 'redundant';
export type V1014SpecializationPhase = 'none' | 'emerging' | 'established' | 'dominant';

export type V1014DerivedKind =
  | 'city_growth_accelerated'
  | 'city_growth_stalled'
  | 'intercity_link_congested'
  | 'intercity_link_restored'
  | 'metropolitan_specialization_emerged'
  | 'corridor_redundancy_improved';

export interface V1014DerivedEvent {
  id: string; turn: number; kind: V1014DerivedKind; cityId: V1014CityId | null; linkId: string | null;
  regionIds: string[]; text: string; significance: 'minor' | 'meaningful' | 'major';
}

export interface V1014CityProfile {
  id: V1014CityId; name: string; regionId: string; popBand: string; coastal: boolean;
  narrative: string; primarySectors: string[]; secondarySectors: string[]; gateway: boolean;
  absorptionNotes: string[]; infrastructureHooks: string[];
}

export interface V1014IntercityLinkDef {
  id: string; kind: V1014LinkKind; cityA: V1014CityId; cityB: V1014CityId;
  baselineCapacity: number; redundancyGroup: string; strategic: boolean; label: string;
}

export interface V1014CitySnapshot {
  cityId: V1014CityId; regionId: string; growthScore: number; growthBand: V1014GrowthBand;
  absorptionHeadroom: number; specializationPhase: V1014SpecializationPhase; primarySector: string | null;
  congestionExposure: number; corridorHealth: number; summary: string; evidence: string[];
}

export interface V1014LinkSnapshot {
  linkId: string; kind: V1014LinkKind; health: V1014LinkHealth; utilization: number;
  congestionBand: V1014CongestionBand; redundancyScore: number; summary: string;
}

export interface V1014CityRegionalState {
  schemaVersion: '10.14.0'; revision: number; turn: number;
  cities: Record<V1014CityId, V1014CitySnapshot>;
  links: Record<string, V1014LinkSnapshot>;
  nationalCorridorSummary: string; inputHash: string; computeMs: number;
}

export interface V1014HistoryEntry { id: string; turn: number; kind: string; subject: string; summary: string; }

export interface V1014CityMemory { growthBand: V1014GrowthBand; specializationPhase: V1014SpecializationPhase; pinnedSector: string | null; sinceTurn: number; }
export interface V1014LinkMemory { health: V1014LinkHealth; utilizationEwma: number; sinceTurn: number; }

export interface V1014CityRegionalPersisted {
  schemaVersion: '10.14.0'; revision: number; initializedTurn: number | null;
  cities: Partial<Record<V1014CityId, V1014CityMemory>>;
  links: Record<string, V1014LinkMemory>;
  history: V1014HistoryEntry[]; seq: number; inputHash: string;
}

export interface V1014Inputs {
  turn: number;
  lrRegions: Record<string, { name: string; momentumBand: string; developmentTier: string; economyScore: number;
    specializations: { primary: string | null; secondary: string | null; emerging: string | null; sectors: Record<string, number> };
    infrastructureQuality: number; needs: Array<{ category: string; severity: string; status: string }>;
  }>;
  networkFreight: number; networkDigital: number; activeProjects: Array<{ regionId: string; projectType: string; status: string }>;
}

const v1014R = (x: number, d = 1) => { const f = 10 ** d; return Math.round((Number.isFinite(x) ? x : 0) * f) / f; };
const v1014C = (x: number, a = 0, b = 100) => Math.max(a, Math.min(b, Number.isFinite(x) ? x : 0));

