export function v1014AnswerQuestion(q: string, state: V1014CityRegionalState | null): string | null {
  for (const p of V1014_AI_QUESTION_PATTERNS) { if (p.pattern.test(q)) return p.answer({ state }); }
  if (/intercity|corridor|rail link/i.test(q) && state) {
    const bad = Object.values(state.links).filter(l => l.congestionBand === 'constrained' || l.congestionBand === 'gridlocked');
    return bad.length ? `Congested corridors: ${bad.slice(0, 3).map(l => l.summary).join('; ')}` : 'No major corridor congestion right now.';
  }
  return null;
}

