export function runV1014FixtureSweep(): { passed: number; total: number } {
  let passed = 0;
  for (const fx of V1014_FIXTURE_SCENARIOS) {
    const r = recomputeV1014CityRegionalState(fx.inputs, null);
    if (fx.expect.city && r.state.cities[fx.expect.city]) passed += 1;
    else if (!fx.expect.city) passed += 1;
  }
  return { passed, total: V1014_FIXTURE_SCENARIOS.length };
}

