export function v1014LookupPlaybook(cityId: V1014CityId, sector: string, growthBand: V1014GrowthBand): V1014GrowthPlaybookEntry | null {
  return V1014_METRO_GROWTH_PLAYBOOKS.find(p => p.cityId === cityId && p.sector === sector && p.growthBand === growthBand) || null;
}

